--- /dev/null
+++ b/src/webhooks/deliver.ts
@@ -0,0 +1,44 @@
+import { createHmac } from 'node:crypto'
+import type { QueuedDelivery } from './store'
+
+const timeoutMs = 10_000
+
+export type DeliveryOutcome =
+  | { kind: 'delivered' }
+  | { kind: 'retry'; error: string }
+  | { kind: 'permanent-failure'; error: string }
+
+export async function deliverOnce(
+  delivery: QueuedDelivery,
+  secret: string,
+): Promise<DeliveryOutcome> {
+  const body = JSON.stringify(delivery.payload)
+  const signature = createHmac('sha256', secret).update(body).digest('hex')
+
+  try {
+    const response = await fetch(delivery.endpoint, {
+      method: 'POST',
+      headers: {
+        'content-type': 'application/json',
+        'x-webhook-id': delivery.eventId,
+        'x-webhook-signature': signature,
+      },
+      body,
+      signal: AbortSignal.timeout(timeoutMs),
+    })
+
+    if (response.ok) return { kind: 'delivered' }
+
+    // A rejected payload or a missing endpoint will fail again. A timeout, a rate
+    // limit, or a server error is worth another attempt later.
+    const retryable = response.status === 429 || response.status >= 500
+    return retryable
+      ? { kind: 'retry', error: `HTTP ${response.status}` }
+      : { kind: 'permanent-failure', error: `HTTP ${response.status}` }
+  } catch (error) {
+    return {
+      kind: 'retry',
+      error: error instanceof Error ? error.message : 'Network error',
+    }
+  }
+}

diff --git a/src/observability/metrics.ts b/src/observability/metrics.ts
new file mode 100644
--- /dev/null
+++ b/src/observability/metrics.ts
@@ -0,0 +1,15 @@
+export type DeliveryResult = 'delivered' | 'retrying' | 'exhausted'
+
+const totals: Record<DeliveryResult, number> = {
+  delivered: 0,
+  retrying: 0,
+  exhausted: 0,
+}
+
+export function recordDelivery(result: DeliveryResult): void {
+  totals[result] += 1
+}
+
+export function webhookMetrics(): Record<DeliveryResult, number> {
+  return { ...totals }
+}

